import React, { useState, useEffect } from "react";
import { useNavigate, useSearchParams } from "react-router-dom";
import { XCircle } from "lucide-react";

import {
  Screen,
  PrimaryButton,
} from "../components/common/UI";

import "../styles/PaymentFailed.css";

export default function PaymentFailed() {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const [order, setOrder] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // TODO: Replace with actual API call to GET /orders/:orderId
    // Get orderId from URL params
    setOrder({
      _id: "1",
      public_id: "GR-98312",
      total: { kes: "564.00", aud: "6.24" }
    });
    setLoading(false);
  }, [searchParams]);

  if (loading) {
    return <Screen title="Payment Status">Loading...</Screen>;
  }

  const handleTryAgain = async () => {
    // TODO: Implement API call to POST /orders/:orderId/pay
    // This will create a new Stripe checkout session
    // Then redirect to the payment URL
  };

  return (
    <Screen title="Payment Status">
      <div className="payment-result failed-result">
        <XCircle
          size={75}
          color="#df2935"
        />

        <h2>Payment Failed</h2>

        <p>
          We could not confirm your payment.
          Please try again or contact support if the issue persists.
        </p>

        {order && (
          <div className="panel">
            <div className="summary-line">
              <span>Order</span>
              <b>{order.public_id}</b>
            </div>
            <div className="summary-line">
              <span>Total</span>
              <b className="orange">
                KSh {order.total.kes}
                <span className="aud-price">≈ AUD {order.total.aud}</span>
              </b>
            </div>
          </div>
        )}

        <PrimaryButton
          variant="red"
          onClick={handleTryAgain}
        >
          Try Again
        </PrimaryButton>

        <button
          className="text-action"
          onClick={() => navigate("/orders")}
        >
          View Orders
        </button>
      </div>
    </Screen>
  );
}
